@* Popup with common emoji reactions *@

<div class="emoji-picker">
    @foreach (var emoji in Emojis)
    {
        <button class="emoji-btn" @onclick="() => OnEmojiSelected.InvokeAsync(emoji)"
                @onclick:stopPropagation="true">
            @emoji
        </button>
    }
</div>

@code {
    [Parameter] public EventCallback<string> OnEmojiSelected { get; set; }

    private static readonly string[] Emojis = ["👍", "❤️", "😂", "🎉", "😮", "👀"];
}

.emoji-picker {
    display: flex;
    gap: 0.25rem;
    padding: 0.35rem 0.5rem;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.12);
    position: absolute;
    bottom: 100%;
    right: 0;
    margin-bottom: 4px;
