    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem 0.3rem;
    border-radius: 4px;
    transition: background 0.1s;
    line-height: 1;
}

.emoji-btn:hover {
    background: #f0f0f0;
}

