@using sv_b23ae6fe27d649f99ad872a6aad898c6.Services

<div class="message-area">
    @if (Channel is not null)
    {
        <div class="area-header">
            <h3># @Channel.Name</h3>
            <span class="area-desc">@Channel.Description</span>
        </div>

        <div class="message-list" @onscroll="HandleScroll" @ref="messageListRef">
            @if (IsLoadingMore)
            {
                <div class="loading-indicator">Loading older messages...</div>
            }
            @if (HasMore && !IsLoadingMore)
            {
                <button class="load-more-btn" @onclick="OnLoadMore">Load older messages</button>
            }

            @foreach (var msg in Messages)
            {
                <MessageBubble Message="msg"
                               ReplyCount="GetReplyCount(msg.Id)"
                               OnOpenThread="OnOpenThread"
                               OnEmojiReact="OnEmojiReact" />
            }
        </div>

        <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                      ButtonLabel="Send"
                      OnSend="OnSendMessage" />
    }
    else
    {
        <div class="no-channel">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter] public Channel? Channel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool HasMore { get; set; }
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnEmojiReact { get; set; }

    private ElementReference messageListRef;

    private int GetReplyCount(int messageId)
        => ThreadReplyCounts.GetValueOrDefault(messageId);

    private async Task HandleScroll()
    {
        // Scroll-to-top pagination is handled via the "Load older messages" button
        // as JS interop for scroll position would add complexity
        await Task.CompletedTask;
    }
}

