.loading-indicator {
    text-align: center;
    padding: 0.75rem;
    font-size: 0.8rem;
    color: #999;
}

.load-more-btn {
    display: block;
    margin: 0.5rem auto;
    background: none;
    border: 1px solid #ccc;
    border-radius: 4px;
