arguments.file_text:
@page "/chat"
@using sv_b23ae6fe27d649f99ad872a6aad898c6.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="sidebar-column">
        <ChannelSidebar Channels="channels"
                        SelectedChannelId="selectedChannel?.Id"
                        OnChannelSelected="HandleChannelSelected" />
    </div>

    <div class="main-column" style="@MainColumnStyle">
        <MessageArea Channel="selectedChannel"
                     Messages="messages"
                     ThreadReplyCounts="threadReplyCounts"
                     HasMore="hasMore"
                     IsLoadingMore="isLoadingMore"
                     OnLoadMore="HandleLoadMore"
                     OnSendMessage="HandleSendMessage"
                     OnOpenThread="HandleOpenThread"
                     OnEmojiReact="HandleEmojiReact" />
    </div>

    @if (isThreadOpen && threadRootMessage is not null)
    {
        <div class="thread-column">
            <ThreadPanel RootMessage="threadRootMessage"
                         ThreadMessages="threadMessages"
                         OnClose="HandleCloseThread"
                         OnSendReply="HandleSendReply"
                         OnEmojiReact="HandleEmojiReact" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private Dictionary<int, int> threadReplyCounts = [];

    private Message? threadRootMessage;
    private List<Message> threadMessages = [];
    private bool isThreadOpen;

    private bool isLoadingMore;
    private bool hasMore = true;

    private const int PageSize = 30;

    private string MainColumnStyle => isThreadOpen
        ? "flex: 0 0 55%;"
        : "flex: 1;";

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();

        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        if (selectedChannel is null) return;

        messages = [];
        hasMore = true;
        threadReplyCounts = [];

        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messages = loaded;
        hasMore = loaded.Count >= PageSize;

        BuildThreadReplyCounts();

        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count locally
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = selectedChannel with { UnreadCount = 0 };
            selectedChannel = channels[idx];
        }

        // Close any open thread when switching channels
        isThreadOpen = false;
        threadRootMessage = null;
        threadMessages = [];
    }

    private async Task HandleChannelSelected(int channelId)
    {
        await SelectChannel(channelId);
    }

    private async Task HandleLoadMore()
    {
        if (isLoadingMore || selectedChannel is null) return;

        isLoadingMore = true;
